#!/usr/bin/env node
// Writes docs/approach-methodologies.md from registry/methodologies/. Edit those files, not the doc.
import { writeFileSync } from 'node:fs';
import { loadMethodologies } from '../src/design/spec.mjs';

const out = [
  '<!-- Generated by scripts/gen-methodologies-doc.mjs from registry/methodologies/. -->',
  '',
  '# The eight approaches as design methodologies',
  '',
  'Each approach is a complete way of designing a site, not a set of sections. A site follows one, as a whole. Another approach joins only when the methodology lists it under "Combines with", the direction gives a written reason, and the operator approves it at B2.',
  '',
  'The "From the team" lines come from the Master Review workbook and the approach skills. The "Interpretation" lines are harness authors\' reading and should be checked against Nidhi\'s approach definitions.',
  '',
];
for (const m of loadMethodologies()) {
  out.push(`## ${m.id} ${m.name}`, '', m.philosophy, '');
  out.push(`**Principles**`, '', ...m.principles.map((p) => `- ${p}`), '');
  const row = (label, text) => out.push(`**${label}:** ${text}`, '');
  row('Visual identity', m.visualIdentity);
  row('Art direction', m.artDirection);
  row('Layout and composition', `${m.layout.composition} Patterns: ${m.layout.patterns.map((p) => `\`${p}\``).join(', ')}.`);
  row('Typography', m.typography);
  row('Colour', m.colour);
  row('Content', m.contentPresentation);
  row('Images and assets', m.assets);
  row('Animation and interaction', m.animation);
  row('Scrolling and transitions', m.scrolling);
  row('Responsive', m.responsive);
  row('Use for', m.useCases.join('; '));
  row('Avoid for', m.avoidFor.join('; '));
  row('Combines with', m.compatibleWith.length ? m.compatibleWith.map((c) => `${c.approach} (${c.when})`).join('; ') : 'nothing');
  row('The render check requires', `${m.signals.required.join(', ') || 'nothing special'}; forbids ${m.signals.forbidden.join(', ') || 'nothing'}`);
  row('From the team', m.provenance.fromTeam.join('. '));
  row('Interpretation', m.provenance.interpreted.join('. '));
}
writeFileSync(new URL('../docs/approach-methodologies.md', import.meta.url), out.join('\n'));
